	@Test
	void generatedBlankNodesSpillAsCompactlyAsPlainOnesWithoutJavaSerialization() throws IOException {
		BNode generated = new BlankNodeAllocationScope("generated-", ignored -> false).createBNode(vf);
		byte[] generatedBytes = bytes(new ValueSerializer(vf), generated);
		byte[] plainBytes = bytes(new ValueSerializer(vf), vf.createBNode(generated.getID()));

		assertEquals(plainBytes.length, generatedBytes.length, "only the type tag tells them apart");
		assertFalse(containsJavaStreamMagic(generatedBytes), "no ObjectOutputStream in a spilled blank node");
		assertNotEquals(plainBytes[0], generatedBytes[0]);
	}

