	private static boolean containsJavaStreamMagic(byte[] bytes) {
		for (int index = 0; index + 1 < bytes.length; index++) {
			if (bytes[index] == (byte) 0xAC && bytes[index + 1] == (byte) 0xED) {
				return true;
			}
		}
		return false;
	}

